#!/bin/bash
set -euo pipefail

# ─── Regenerate ForeverLM.xcodeproj from project.yml ─────────────────────────
# `project.pbxproj` is generated by XcodeGen but committed, so a fresh clone can
# build without XcodeGen installed. That only holds while the committed file
# actually matches `project.yml`, and a stale project is silent: it builds fine,
# it just omits whatever `project.yml` gained since. That is how a release once
# archived without an app icon change that was already committed and pushed.
#
# The original cause was iCloud. The checkout used to live under ~/Documents
# with iCloud Drive's Desktop & Documents sync on, and iCloud restored an older
# `project.pbxproj` over a freshly generated one and left "ForeverLM 2.xcodeproj"
# conflict copies behind. The repos now live in ~/Developer/GitHub, outside the
# synced tree, with a symlink left at the old path.
#
# The remaining way to drift is ordinary: several agent sessions share this
# checkout, and one can add a source file and regenerate while another builds.
# So every build path that matters still runs this first. Regenerating is
# idempotent — when nothing has drifted it rewrites the same bytes and says so.
#
# Usage:
#   ./scripts/sync_project.sh            # regenerate, report drift, exit 0
#   ./scripts/sync_project.sh --strict   # also exit 1 if anything had drifted
# ─────────────────────────────────────────────────────────────────────────────

STRICT=false
[ "${1:-}" = "--strict" ] && STRICT=true

PROJECT_DIR="$(cd "$(dirname "$0")/.." && pwd)"
PBXPROJ="${PROJECT_DIR}/ForeverLM.xcodeproj/project.pbxproj"

info()  { echo "▸ $*"; }
warn()  { echo "⚠ $*" >&2; }
error() { echo "✗ $*" >&2; exit 1; }

if ! command -v xcodegen &>/dev/null; then
    # Never fall through to a build here. The whole point is that a stale
    # project still builds, so skipping the regeneration hides the problem.
    error "xcodegen not found. Install it with: brew install xcodegen"
fi

before=""
[ -f "$PBXPROJ" ] && before="$(shasum -a 256 "$PBXPROJ" | cut -d' ' -f1)"

info "Regenerating ForeverLM.xcodeproj from project.yml..."
(cd "$PROJECT_DIR" && xcodegen generate --quiet)

[ -f "$PBXPROJ" ] || error "xcodegen did not produce ${PBXPROJ}"
after="$(shasum -a 256 "$PBXPROJ" | cut -d' ' -f1)"

# iCloud resolves a sync conflict by keeping both copies, and a stray
# "ForeverLM 2.xcodeproj" is a strong hint the real one was rewritten underneath
# us. Report them; they are ignored by git but confuse anyone opening the folder.
conflicts=()
while IFS= read -r -d '' candidate; do
    conflicts+=("$candidate")
done < <(find "$PROJECT_DIR" -maxdepth 1 -name "* [0-9].xcodeproj" -print0 2>/dev/null)

if [ ${#conflicts[@]} -gt 0 ]; then
    warn "iCloud left ${#conflicts[@]} conflict copy/copies of the project:"
    for c in "${conflicts[@]}"; do warn "    ${c##*/}"; done
    warn "Delete them; they are stale and are not the project anything builds."
fi

if [ "$before" = "$after" ]; then
    info "Project already matched project.yml."
    exit 0
fi

if [ -z "$before" ]; then
    info "Project did not exist and has been generated."
    exit 0
fi

warn "project.pbxproj did NOT match project.yml and has been regenerated."
warn "Anything built before this ran may have been missing files that project.yml lists."
if git -C "$PROJECT_DIR" diff --quiet -- "$PBXPROJ" 2>/dev/null; then
    warn "The regenerated project matches the committed one, so only the working copy had drifted."
else
    warn "The committed project is also out of date — commit the regenerated project.pbxproj."
fi

$STRICT && exit 1
exit 0
